var LINKS={1:[{n:2,rel:"stesso filone: l'anatomia che sostiene il razionale del LET"},{n:4,rel:"la stessa domanda sul costrutto, questa volta nella revisione"}],2:[{n:1,rel:"la tassonomia dei costrutti femorali per il LET"}],4:[{n:1,rel:"il costrutto onlay ancora senza confronto diretto"}],5:[{n:6,rel:"stessa tecnica, un altro angolo: dal tunnel al cammino"},{n:8,rel:"lo stesso problema, affrontato in laboratorio"}],6:[{n:5,rel:"il parametro tecnico che potrebbe spiegare parte del quadro"},{n:8,rel:"la centralizzazione che potrebbe correggere l'estrusione residua"}],8:[{n:5,rel:"il dato clinico sullo stesso problema, l'estrusione"},{n:6,rel:"il cammino che la riparazione da sola non normalizza"}]};
